/** Build process module type completions. */
function processTypeCompletions(): StdlibExternalCompletionDefinition[] {
  return processTypeNames.map((name) => ({
    detail: `process: type ${name}`,
    documentation: stdlibErrorDocumentation(name) ?? `Process-module type \`${name}\` used by process path and environment APIs.`,
    moduleName: 'process',
    name,
    typeOnly: true
  }));
}

/** Build system prerequisite type and error completions. */
function systemTypeCompletions(moduleOverride?: string): StdlibExternalCompletionDefinition[] {
  return systemTypeNames
    .filter((name) => moduleOverride !== 'standard' || !standardTypeNames.includes(name))
    .map((name) => ({
      detail: `${moduleOverride ?? 'standard.system'}: type ${name}`,
      documentation: stdlibSystemTypeDocumentation(name) ?? `System prerequisite type \`${name}\` used by wait, timer, process-control, cancellation, and error-inspection APIs.`,
      moduleName: moduleOverride ?? 'standard.system',
      name,
      typeOnly: true
    }));
}

/** Build every named error set currently registered by standard.errors. */
function allStandardErrorSetCompletions(): StdlibExternalCompletionDefinition[] {
  return standardErrorFamilies.map((family) => ({
    detail: `standard.errors: ${family.name} = ${family.members.join(', ')}`,
    documentation: stdlibErrorSetDocumentation(family.name, family.members),
    moduleName: 'standard.errors',
    name: family.name,
    typeOnly: true
  }));
}

/** Build terminal proposal function completions from the registered signature inventory. */
function terminalFunctionCompletions(moduleOverride?: string): StdlibExternalCompletionDefinition[] {
  return terminalFunctionSpecs
    .filter((spec) => !moduleOverride || spec.moduleName !== 'standard.testing.terminal')
    .map((spec) => ({
      detail: `${moduleOverride ?? spec.moduleName}: ${terminalSignature(spec)}`,
      documentation: terminalFunctionDocumentation(spec),
      moduleName: moduleOverride ?? spec.moduleName,
      name: spec.name
    }));
}

/** Build terminal proposal type completions from authoritative declaration docs. */
function terminalTypeCompletions(moduleOverride?: string): StdlibExternalCompletionDefinition[] {
  return terminalTypeSpecs
    .filter((spec) => !moduleOverride || spec.moduleName !== 'standard.testing.terminal')
    .map((spec) => ({
      detail: `${moduleOverride ?? spec.moduleName}: type ${spec.name}`,
      documentation: spec.documentation,
      moduleName: moduleOverride ?? spec.moduleName,
      name: spec.name,
      typeOnly: true
    }));
}

/** Format a terminal function signature from compact metadata. */
function terminalSignature(spec: TerminalFunctionSpec): string {
  const params = spec.parameters.map((typeName, index) => `${parameterNameForTerminalType(typeName, index)}: ${typeName}`).join(', ');
  const errors = spec.errors.length > 0 ? ` errors ${spec.errors.join(', ')}` : '';
  return `${spec.name}(${params}): ${spec.returnType}${errors}`;
}

/** Pick readable parameter names for generated stdlib signatures. */
function parameterNameForTerminalType(typeName: string, index: number): string {
  const normalized = typeName.endsWith('[]') ? typeName.slice(0, -2) : typeName;
  const byType = new Map<string, string>([
    ['TerminalSessionOptions', 'options'],
    ['TerminalSession', 'session'],
    ['TerminalRecoveryToken', 'token'],
    ['TerminalCapabilities', 'capabilities'],
    ['TerminalInputEvent', 'event'],
    ['TerminalChordRouter', 'router'],
    ['TerminalChordSequence', 'sequence'],
    ['TerminalChord', 'chord'],
    ['TerminalChordBindingId', 'binding_id'],
    ['SystemWaitSet', 'wait_set'],
    ['SystemReadinessSource', 'source'],
    ['CancellationSource', 'source'],
    ['CancellationToken', 'token'],
    ['MonotonicTimer', 'timer'],
    ['Error', 'error'],
    ['ErrorAttachmentTruncation', 'truncation'],
    ['TerminalDiagnostic', 'diagnostic'],
    ['TerminalDiagnosticCollection', 'diagnostics'],
    ['TerminalPauseEvents', 'events'],
    ['TerminalChordReleasedInput', 'input'],
    ['uint64', 'generation'],
    ['int64', 'index'],
    ['TerminalTestScenario', 'scenario'],
    ['TerminalTestAuthority', 'authority'],
    ['string', 'text'],
    ['boolean', 'value']
  ]);
  return byType.get(normalized) ?? `arg${index + 1}`;
}

